<?php
declare(strict_types=1);
namespace App\Controller;
use App\Message\CollectFeedMessage; use Doctrine\ORM\EntityManagerInterface; use Symfony\Bundle\FrameworkBundle\Controller\AbstractController; use Symfony\Component\HttpFoundation\Request; use Symfony\Component\HttpFoundation\Response; use Symfony\Component\Messenger\MessageBusInterface; use Symfony\Component\Routing\Attribute\Route; use Symfony\Component\Uid\Uuid;
final class AdminFeedSyncController extends AbstractController
{
 #[Route('/admin/feed-sync', name:'app_admin_feed_sync_start',methods:['POST'])] public function start(Request $r,EntityManagerInterface $em,MessageBusInterface $bus):Response { $this->denyAccessUnlessGranted('ROLE_ADMIN');$csrfToken=$r->headers->get('X-CSRF-Token') ?? $r->request->getString('_token');if(!$this->isCsrfTokenValid('admin-feed-sync',$csrfToken))throw $this->createAccessDeniedException();$scope=$r->request->getString('scope');$sql='SELECT DISTINCT f.id FROM feed f';$params=[];if('category'===$scope){$sql.=' INNER JOIN subscription s ON s.feed_id=f.id WHERE s.category_id=?';$params=[Uuid::fromString($r->request->getString('category'))->toBinary()];}elseif('feed'===$scope){$sql.=' WHERE f.id=?';$params=[Uuid::fromString($r->request->getString('feed'))->toBinary()];}elseif('all'!==$scope)throw $this->createNotFoundException();$ids=$em->getConnection()->fetchFirstColumn($sql,$params);$run=Uuid::v7();$db=$em->getConnection();$db->insert('feed_sync_run',['id'=>$run->toBinary(),'created_at'=>(new \DateTimeImmutable())->format('Y-m-d H:i:s')]);foreach($ids as $id){$db->insert('feed_sync_run_entry',['run_id'=>$run->toBinary(),'feed_id'=>$id,'status'=>'pending','new_articles'=>0]);$bus->dispatch(new CollectFeedMessage((string)Uuid::fromBinary($id),(string)$run));}if('application/json' !== $r->headers->get('Accept')){$this->addFlash('success',sprintf('%d flux placés en file de synchronisation.',count($ids)));return $this->redirectToRoute('app_admin',status:Response::HTTP_SEE_OTHER);}return $this->json(['runId'=>(string)$run,'count'=>count($ids)],202); }
 #[Route('/admin/feed-sync/{id}', name:'app_admin_feed_sync_status',methods:['GET'])] public function status(string $id,EntityManagerInterface $em):Response{$this->denyAccessUnlessGranted('ROLE_ADMIN');$rows=$em->getConnection()->fetchAllAssociative('SELECT f.title,f.canonical_url,e.status,e.new_articles,e.detail FROM feed_sync_run_entry e INNER JOIN feed f ON f.id=e.feed_id WHERE e.run_id=? ORDER BY f.title, f.canonical_url',[Uuid::fromString($id)->toBinary()]);return $this->json(['entries'=>$rows,'complete'=>!array_filter($rows,fn($r)=>in_array($r['status'],['pending','running'],true))]);}
}
